import java.util.*;

class Solution {
    public int[] twoSum(int[] nums, int target) {
        int i = 0, j = nums.length - 1;
        while (i < j) {
            long s = (long) nums[i] + nums[j];
            if (s == target) return new int[]{i + 1, j + 1}; // 1-based positions
            if (s < target) i++;   // need a bigger sum
            else j--;              // need a smaller sum
        }
        return new int[]{-1, -1}; // not reached: a pair always exists
    }
}

